{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "AM281, the closest analogue (Morgan 0.579), is directly BBB-permeable in humans and enabled CB1 quantification; however, it contains a morpholine and p-iodophenyl instead of the query's more polar thiomorpholine-dioxide and cyanopentynyl substituents, so this permeable phenotype does not fully transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Compound 18a, a close scaffold analogue with a polar Boc-piperidine carboxamide at the same position as the query's sulfone-hydrazide, showed little to no CNS penetration with a very low brain:plasma ratio.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "MJ15, a close analogue with a polar pyridylmethyl amide, showed lowered propensity to pass the BBB in mice, supporting that polar amide-region modifications in this scaffold reduce CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "AM5144, a related pyrazole CB1 ligand with a polar amide and bromophenyl, showed very low absolute brain uptake (<0.003% ID/cc) in baboon PET, indicating that polar variants of this scaffold can be poorly brain-penetrant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Compound 2s showed a brain/plasma ratio of 0.48 in mice and was considered good penetration, but it is structurally more distant and lacks the sulfone and nitrile polarity of the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted fail: although the closest AM281 analogues are brain-permeable, the query's replacement of morpholine with thiomorpholine-1,1-dioxide and addition of a polar cyanopentynyl chain introduce substantial polarity and likely limited passive permeability/efflux liabilities; lower-similarity but mechanistically relevant analogues with polar amide-region substituents show little or no CNS penetration.",
  "evidence_gaps": [
    "No direct brain/plasma or PET data for the exact query or a thiomorpholine-dioxide analogue",
    "Transporter-mediated efflux (P-gp/BCRP) status of the query is unknown",
    "The relevance of human AM281 permeability to the sulfone-modified query is uncertain"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

